const fs = require('fs');
const statePath = '/etc/geivs/geivs-state.json';

try {
  const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  const integrations = state.integrations;

  // Build clean status summary
  const status = {
    geivs_version: state.geivs_version,
    persona: state.persona,
    onboarding_complete: state.onboarding_complete,
    first_boot_at: state.first_boot_at,
    integrations: {}
  };

  // Summarize each integration
  for (const [key, value] of Object.entries(integrations)) {
    status.integrations[key] = {
      configured: value.configured,
      details: value.configured ? getSummary(key, value) : 'Not configured'
    };
  }

  return [{ json: { success: true, dashboard: status } }];
} catch(e) {
  return [{ json: { success: false, error: 'Could not read GEIVS state: ' + e.message } }];
}

function getSummary(key, value) {
  switch(key) {
    case 'email': return value.address || value.provider;
    case 'signal': return value.phone_number;
    case 'telegram': return '@' + (value.bot_name || 'configured');
    case 'google_calendar': return 'Google Calendar connected';
    case 'outlook_calendar': return 'Outlook Calendar connected';
    case 'google_drive': return 'Google Drive connected';
    case 'nextcloud': return value.url;
    case 'postiz': return (value.platforms || []).join(', ') || 'configured';
    default: return 'configured';
  }
}

const fs = require('fs');
const statePath = '/etc/geivs/geivs-state.json';

try {
  const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  state.onboarding_complete = true;
  state.last_seen = new Date().toISOString();
  fs.writeFileSync(statePath, JSON.stringify(state, null, 4));
  return [{ json: { success: true, message: 'Onboarding marked as complete. Welcome to GEIVS.' } }];
} catch(e) {
  return [{ json: { success: false, error: e.message } }];
}

const body = $input.first().json.body;
const fs = require('fs');
const statePath = '/etc/geivs/geivs-state.json';

const name = body.name;
const gender = body.gender || 'male';
const voice = gender === 'female' ? 'en_GB-alba-medium' : 'en_GB-alan-medium';

if (!name) {
  return [{ json: { success: false, error: 'Name is required' } }];
}

try {
  const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  state.persona = { name, gender, voice };
  fs.writeFileSync(statePath, JSON.stringify(state, null, 4));
  return [{ json: { 
    success: true, 
    message: 'Very good. I shall answer to ' + name + ' from this point forward.',
    persona: state.persona
  } }];
} catch(e) {
  return [{ json: { success: false, error: e.message } }];
}
